// === Tab: lookatme ===
let n,p;
let r,ww,hh;

let run = true;
function setup() {
  createCanvas(600, 600);
  n = 20;
  n2 = n/2;
  p = 3;
  r = width/(2*n);
  ww = width/n;
  hh = height/n;
}

function draw() {
  if (run) {
  background(0);
  for (i=0;i<n;i++) {
     for (j=0;j<n;j++) {
      animate(i,j);
     }
  }
 }
}

function animate(i,j) {
  pushMatrix();
  translate(i*ww+r, j*hh+r);
  rotate((frameCount/300)*(abs(n2-i)+abs(n2-j)));
  polygon(0, 0, r, p);  
  popMatrix();
}

function polygon(x, y, radius, npoints) {
  let angle = TWO_PI / npoints;
  beginShape();
  for (a = 0; a < TWO_PI; a += angle) {
    let sx = x + cos(a) * radius;
    let sy = y + sin(a) * radius;
    vertex(sx, sy);
  }
  endShape(CLOSE);
}

function mouseClicked() {
  run = !run;
}

